import{c as t,Q as n,j as s,m as e}from"./chunks/framework.B2dUnTNU.js";const u=JSON.parse('{"title":"锻造与制作系统","description":"","frontmatter":{},"headers":[],"relativePath":"b42/crafting.md","filePath":"b42/crafting.md","lastUpdated":1779619065000}'),l={name:"b42/crafting.md"};function i(d,a,r,o,p,h){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="锻造与制作系统" tabindex="-1">锻造与制作系统 <a class="header-anchor" href="#锻造与制作系统" aria-label="Permalink to &quot;锻造与制作系统&quot;">​</a></h1><p>B42 的核心灵魂——制作系统被<strong>彻底重写</strong>。新增 6 个制作技能，技能之间互相依赖，形成复杂的生产链。老玩家最需要适应的变化：<strong>拆家具不给木工 XP 了</strong>，技能书现在<strong>解锁配方</strong>而不只是 XP 倍率。</p><hr><h2 id="⚠️-b41-→-b42-关键变化" tabindex="-1">⚠️ B41 → B42 关键变化 <a class="header-anchor" href="#⚠️-b41-→-b42-关键变化" aria-label="Permalink to &quot;⚠️ B41 → B42 关键变化&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">拆解不再给木工 XP</p><p>B41 靠拆双人床练木工的时代结束了。B42 <strong>必须通过建造物品</strong>来提升木工等级。早期最佳 XP 来源：造木杆（1 木板 + 1 钉子）。</p></div><div class="warning custom-block"><p class="custom-block-title">技能书解锁配方</p><p>技能书在 B42 不再是&quot;读了赚更多 XP&quot;，而是<strong>你不读就看不到配方</strong>。看到技能书就拿起，尤其是你打算深造的技能线。</p></div><div class="tip custom-block"><p class="custom-block-title">技能互相依赖</p><p>你不能只练一个技能到满级。做金属工具需要陶艺做坩埚，陶艺需要木工做陶轮，石器需要锻造做工具…每一条线都依赖其他线的最低等级。</p></div><hr><h2 id="六大新技能" tabindex="-1">六大新技能 <a class="header-anchor" href="#六大新技能" aria-label="Permalink to &quot;六大新技能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能</th><th>核心功能</th><th>关键工具</th><th>入门门槛</th></tr></thead><tbody><tr><td><strong>锻造 (Blacksmithing)</strong></td><td>冶炼金属、锻打刀剑/工具/钉子</td><td>原始熔炉 → 锻炉 → 铁砧</td><td>中等（需要陶艺+石工配合）</td></tr><tr><td><strong>制陶 (Pottery)</strong></td><td>制作坩埚、储水罐、炊具、砖块</td><td>陶轮 + 窑炉</td><td>低（河边挖粘土即可开始）</td></tr><tr><td><strong>打制石器 (Knapping)</strong></td><td>制作石刀、石斧头、箭头、燧石片</td><td>石头或锤子 + 燧石结核</td><td>极低（捡石头就行）</td></tr><tr><td><strong>雕刻 (Carving)</strong></td><td>削制武器手柄/柄杆、木碗、骨针/鱼钩</td><td>任意小刀（含石刀）</td><td>极低（树枝+小刀）</td></tr><tr><td><strong>石工 (Masonry)</strong></td><td>石基/石墙、砖炉、防御石墙、水泥</td><td>石工凿 + 抹刀</td><td>中等（需 Knapping 做凿子）</td></tr><tr><td><strong>玻璃工艺 (Glassmaking)</strong></td><td>玻璃窗、储存罐、实验室器皿</td><td>粘土塑形工具 + 熔炉</td><td>高（工具稀有）</td></tr></tbody></table><hr><h2 id="制作站升级链" tabindex="-1">制作站升级链 <a class="header-anchor" href="#制作站升级链" aria-label="Permalink to &quot;制作站升级链&quot;">​</a></h2><h3 id="锻造线" tabindex="-1">锻造线 <a class="header-anchor" href="#锻造线" aria-label="Permalink to &quot;锻造线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>篝火炭窑 (Fire Pit Charcoal)</span></span>
<span class="line"><span>    │  需要：铲子</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>原始窑炉 (Primitive Kiln)</span></span>
<span class="line"><span>    │  需要：粘土</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>原始熔炉 (Primitive Furnace)</span></span>
<span class="line"><span>    │  需要：雕刻木桶 + 粘土 + 水泥</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>原始锻炉 (Primitive Forge)</span></span>
<span class="line"><span>    │  需要：石砧（石工制作）</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>高级锻炉 + 铁砧</span></span>
<span class="line"><span>    │  可锻造：刀剑、斧头、钉子、工具零件</span></span></code></pre></div><h3 id="陶艺线" tabindex="-1">陶艺线 <a class="header-anchor" href="#陶艺线" aria-label="Permalink to &quot;陶艺线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>河边采集粘土</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>陶艺台 (Pottery Bench) —— 木工制作</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>陶轮 (Pottery Wheel) —— 木工制作</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>塑造器皿（小件可徒手，大件需陶轮）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>窑炉烧制 (Kiln) —— 烧制陶器和坩埚</span></span></code></pre></div><h3 id="石器线" tabindex="-1">石器线 <a class="header-anchor" href="#石器线" aria-label="Permalink to &quot;石器线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>采集燧石结核（觅食获得）或开采石矿</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>敲击燧石片 (Knap Flint Flakes) —— 练到 Lv2</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>制作石斧头 (Stone Axe Head) —— 10x XP</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>制作石工凿 (Masonry Chisel) —— 开启石工线</span></span></code></pre></div><hr><h2 id="关键配方速查" tabindex="-1">关键配方速查 <a class="header-anchor" href="#关键配方速查" aria-label="Permalink to &quot;关键配方速查&quot;">​</a></h2><h3 id="锻造入门" tabindex="-1">锻造入门 <a class="header-anchor" href="#锻造入门" aria-label="Permalink to &quot;锻造入门&quot;">​</a></h3><table tabindex="0"><thead><tr><th>产品</th><th>需要等级</th><th>关键材料</th><th>用途</th></tr></thead><tbody><tr><td>铁锭</td><td>Lv1</td><td>废铁 + 木炭 + 熔炉</td><td>基础原料</td></tr><tr><td>钢锭</td><td>Lv3</td><td>铁锭 + 木炭 + 锻炉</td><td>高级原料</td></tr><tr><td>钉子</td><td>Lv1</td><td>铁锭 + 锻炉</td><td>解决钉子焦虑</td></tr><tr><td>粗制剑刃</td><td>Lv8</td><td>钢锭 + 锻炉 + 铁砧</td><td>自制刀剑</td></tr><tr><td>剑刃</td><td>Lv10</td><td>钢锭 + 高级锻炉</td><td>终局刀剑</td></tr></tbody></table><h3 id="锻造冲级技巧" tabindex="-1">锻造冲级技巧 <a class="header-anchor" href="#锻造冲级技巧" aria-label="Permalink to &quot;锻造冲级技巧&quot;">​</a></h3><ul><li>Lv4-5 期间：批量制作<strong>带扣 (Buckle)</strong>——每只需 1 块钢，但制作钢条本身给大量 XP</li><li>木炭生产：<strong>篝火法</strong>（需铲子）或<strong>炭桶法</strong>（任意金属桶，不占地）</li></ul><h3 id="武器制作路线" tabindex="-1">武器制作路线 <a class="header-anchor" href="#武器制作路线" aria-label="Permalink to &quot;武器制作路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>武器</th><th>需求</th></tr></thead><tbody><tr><td><strong>早期</strong></td><td>单手短棍类（管钳/锤子/扳手/平底锅）</td><td>搜刮即用</td></tr><tr><td></td><td>石刀 (Stone Knife)</td><td>Knapping Lv1</td></tr><tr><td></td><td>粗制石斧 (Crude Stone Axe)</td><td>Knapping Lv1 + Maintenance Lv1</td></tr><tr><td><strong>中期</strong></td><td>轨钉棒球棍 (Railspike Bat)</td><td>Carpentry Lv4 + 杂志</td></tr><tr><td></td><td>大石斧 (Large Stone Axe)</td><td>Knapping Lv3 + Maintenance Lv1 + 杂志</td></tr><tr><td></td><td>矛 (加刀/猎刀)</td><td>Carving + 搜刮刀片</td></tr><tr><td><strong>晚期</strong></td><td>铁板加固棒球棍 (Sheet Metal Reinforced Bat)</td><td>Metalworking 投资</td></tr><tr><td></td><td>锻造刀/砍刀 (Forged Knife/Machete)</td><td>Metalworking Lv8+</td></tr><tr><td></td><td>锻造剑 (Forged Sword)</td><td>Metalworking Lv10</td></tr></tbody></table><hr><h2 id="旧技能的变化" tabindex="-1">旧技能的变化 <a class="header-anchor" href="#旧技能的变化" aria-label="Permalink to &quot;旧技能的变化&quot;">​</a></h2><h3 id="木工-carpentry" tabindex="-1">木工 (Carpentry) <a class="header-anchor" href="#木工-carpentry" aria-label="Permalink to &quot;木工 (Carpentry)&quot;">​</a></h3><ul><li>❌ 拆家具不给 XP</li><li>✅ 早期造木杆（1 木板+1 钉子）练级</li><li>支持陶艺台、陶轮等新制作站</li></ul><h3 id="维护-maintenance" tabindex="-1">维护 (Maintenance) <a class="header-anchor" href="#维护-maintenance" aria-label="Permalink to &quot;维护 (Maintenance)&quot;">​</a></h3><ul><li>🔼 重要性大幅提升——直接影响自制物品的寿命</li><li>现在通过战斗使用和修理物品正常获得 XP（修复了之前 Crowbar 不给 XP 的 bug）</li><li>磨练石 (Whetstone) 可打磨刀刃武器</li></ul><h3 id="烹饪-cooking" tabindex="-1">烹饪 (Cooking) <a class="header-anchor" href="#烹饪-cooking" aria-label="Permalink to &quot;烹饪 (Cooking)&quot;">​</a></h3><ul><li>完全重做：新增烟熏、盐腌、干燥等保存方式</li><li>收集鸡蛋 → 烤箱烹饪 → 收获熟蛋（高效 XP）</li><li>屠宰动物时注意收集骨头（给屠宰 XP）</li></ul><h3 id="裁缝-tailoring" tabindex="-1">裁缝 (Tailoring) <a class="header-anchor" href="#裁缝-tailoring" aria-label="Permalink to &quot;裁缝 (Tailoring)&quot;">​</a></h3><ul><li>不能撕衣服获得线了——必须从破布中回收或搜刮</li><li>到达 Lv1 最快方法：把牛仔裤改短裤，或连衣裙改短裙</li><li>Lv1 后：从破布回收线 → 反复贴/拆破布补丁练级</li></ul><h3 id="电工-electrical" tabindex="-1">电工 (Electrical) <a class="header-anchor" href="#电工-electrical" aria-label="Permalink to &quot;电工 (Electrical)&quot;">​</a></h3><ul><li>基本不变：拆电子设备练级</li><li>发电机相关不变</li></ul><h3 id="技工-mechanics" tabindex="-1">技工 (Mechanics) <a class="header-anchor" href="#技工-mechanics" aria-label="Permalink to &quot;技工 (Mechanics)&quot;">​</a></h3><ul><li>杂志更重要了，每种车型（标准/运动/重型）需要各自的杂志</li><li>练级方法不变：&quot;忒修斯之船&quot;拆换零件</li></ul><h3 id="焊接-welding" tabindex="-1">焊接 (Welding) <a class="header-anchor" href="#焊接-welding" aria-label="Permalink to &quot;焊接 (Welding)&quot;">​</a></h3><ul><li>丙烷焊枪、丙烷罐、焊工面罩都是搜刮品，不能制作</li><li>拆废车残骸获取金属练级</li></ul><hr><h2 id="制作协同链" tabindex="-1">制作协同链 <a class="header-anchor" href="#制作协同链" aria-label="Permalink to &quot;制作协同链&quot;">​</a></h2><h3 id="食物自给流水线" tabindex="-1">食物自给流水线 <a class="header-anchor" href="#食物自给流水线" aria-label="Permalink to &quot;食物自给流水线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>木工 → 农耕设施 → 觅食（种子）→ 耕种 → 烹饪（保存）→ 陶艺（储存）</span></span></code></pre></div><h3 id="武器自给流水线" tabindex="-1">武器自给流水线 <a class="header-anchor" href="#武器自给流水线" aria-label="Permalink to &quot;武器自给流水线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>打制石器（基础工具/零件）→ 雕刻（手柄/柄杆）→ 锻造（刀刃/加固件）→ 维护（延长寿命）</span></span></code></pre></div><h3 id="建造流水线" tabindex="-1">建造流水线 <a class="header-anchor" href="#建造流水线" aria-label="Permalink to &quot;建造流水线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>木工（基础结构）→ 石工（石基/石墙/窑炉）→ 锻造（金属加固）</span></span></code></pre></div><hr><h2 id="b42-制作系统的设计目标" tabindex="-1">B42 制作系统的设计目标 <a class="header-anchor" href="#b42-制作系统的设计目标" aria-label="Permalink to &quot;B42 制作系统的设计目标&quot;">​</a></h2><p>B42 制作系统为未来打基础：</p><ol><li><strong>丰富的终局</strong>——不只是&quot;囤物资然后无聊&quot;</li><li><strong>无限服务器</strong>——不需要刷新物资，玩家可从原料造一切</li><li><strong>社区协作</strong>——不同职业促进交易与互动（为 B43+ NPC 做准备）</li><li><strong>完全荒野科技树</strong>——假设没有文明废墟，也能从零造出所有物品</li></ol>`,54)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
